const inputs = $input.all(); // Los dos resultados (femenina y masculina)

// Intentar obtener la información de voces desde cualquier nodo anterior
let voicesInfo = [];
try {
  const vocesRaw = $('Generar 2 objetos').first().json;
  if (Array.isArray(vocesRaw.voices)) {
    voicesInfo = vocesRaw.voices;
  } else if (Array.isArray(vocesRaw)) {
    // En caso de que la estructura sea [{voices: [...]}]
    voicesInfo = vocesRaw[0]?.voices || [];
  }
} catch (e) {
  console.log('No se pudo leer voces del nodo anterior:', e.message);
}

// Fallback por si voicesInfo está vacío
if (!voicesInfo.length) {
  voicesInfo = inputs.map((_, i) => ({
    name: `voz_${i + 1}`,
    libro: 'desconocido',
    subseccion: 'desconocido'
  }));
}

const results = inputs.map((input, index) => {
  const audioBase64 = input.json.audio_base64;
  const alignment = input.json.alignment || input.json.normalized_alignment;

  if (!alignment) throw new Error(`Falta alignment en input ${index}`);

  const chars = alignment.characters;
  const starts = alignment.character_start_times_seconds;
  const ends = alignment.character_end_times_seconds;

  const combined = chars.map((c, i) => ({
    char: c,
    start: starts[i],
    end: ends[i],
  }));

  const words = [];
  let currentWord = '';
  let startTime = null;
  let endTime = null;

  for (let i = 0; i < combined.length; i++) {
    const { char, start, end } = combined[i];

    if (char.match(/[^\s.,!?;:]/)) {
      if (currentWord === '') startTime = start;
      currentWord += char;
      endTime = end;
    }

    const nextChar = combined[i + 1]?.char ?? ' ';
    if (char.match(/\s/) || nextChar.match(/\s/) || i === combined.length - 1) {
      if (currentWord.trim().length > 0) {
        words.push({ word: currentWord.trim(), start: startTime, end: endTime });
        currentWord = '';
        startTime = null;
        endTime = null;
      }
    }
  }

  const wordsJson = JSON.stringify(words, null, 2);

  const { name, libro, subseccion } = voicesInfo[index] || {};
  const safeName = name || `voz_${index + 1}`;
  const safelibro = $('Generar 2 objetos').first().json.libro; 
  const safesubseccion = $('Generar 2 objetos').first().json.subseccion;

  return {
    json: {
      message: `Archivo ${safeName} generado correctamente`,
      voice: safeName,
      wordCount: words.length
    },
    binary: {
      audio: {
        data: audioBase64,
        mimeType: 'audio/mpeg',
        fileName: `audio_${safeName}_${safelibro}_${safesubseccion}.mp3`
      },
      timestamps: {
        data: btoa(unescape(encodeURIComponent(wordsJson))),
        mimeType: 'application/json',
        fileName: `audio_${safeName}_${safelibro}_${safesubseccion}.json`
      }
    }
  };
});

return results;

const inputs = $input.all(); // 2 items: femenina y masculina
const output = [];

for (const item of inputs) {
  const audioBinary = item.binary?.audio;
  const timestampsBinary = item.binary?.timestamps;
  const voice = item.json?.voice || 'voz';
  const libro = item.json?.libro || 'X';
  const subseccion = item.json?.subseccion || 'Y';

  if (audioBinary) {
    output.push({
      json: {
        fileType: 'audio',
        voice,
        libro,
        subseccion
      },
      binary: {
        data: audioBinary
      }
    });
  }

  if (timestampsBinary) {
    output.push({
      json: {
        fileType: 'timestamps',
        voice,
        libro,
        subseccion
      },
      binary: {
        data: timestampsBinary
      }
    });
  }
}

return output;

// Función para limpiar el texto manteniendo solo palabras y signos de puntuación básicos
function limpiarTextoParaTimestamps(texto) {
  if (!texto) return "";

  let limpio = texto
    // 1. Reemplazar paréntesis por pausas explícitas
    .replace(/\(/g, ', ')
    .replace(/\)/g, '. ')

    // 1.5 Proteger expresiones que deben ser una sola unidad (ej: y/o)
    .replace(/\by\s*\/\s*o\b/gi, 'y_o')

    // 2. Reemplazar caracteres no permitidos (manteniendo signos españoles)
    .replace(/[^\w\s.,;:¿?¡!áéíóúÁÉÍÓÚñÑüÜ]/g, ' ')

    // 3. Normalizar espacios múltiples
    .replace(/\s+/g, ' ')

    // 4. Eliminar espacios antes de puntuación (excepto ¿ y ¡)
    .replace(/\s+([.,;:?])/g, '$1')

    // 5. Asegurar espacio después de puntuación
    //    (pero NO separar puntos que estén entre números, ej: 3.000)
    .replace(/([,;:?])\s*/g, '$1 ')
    .replace(/(?<!\d)\.(?!\d)\s*/g, '. ')

    // 6. Asegurar que ¿ y ¡ tengan espacio antes si no es inicio de texto
    .replace(/([a-zA-ZáéíóúÁÉÍÓÚñÑüÜ])([¿¡])/g, '$1 $2')

    // 7. Normalizar espacios finales otra vez
    .replace(/\s+/g, ' ')
    .trim();

  return limpio;
}

// Obtener el texto original
const textoOriginal = $input.first().json.texto_subseccion;

// Limpiar el texto
const textoLimpio = limpiarTextoParaTimestamps(textoOriginal);

// Log para depuración
console.log("Texto original vs limpio:");
console.log("Original (primeros 100 chars):", textoOriginal.substring(0, 100));
console.log("Limpio (primeros 100 chars):", textoLimpio.substring(0, 100));

return [
  {
    json: {
      voices: [
        {
          name: "femenina",
          id: "p18tR9wFA5Ng9WhfWI0o",
          text: textoLimpio,
          subseccion: $input.first().json.id_subseccion,
          libro: $input.first().json.id_libro,
        },
        {
          name: "masculina",
          id: "htFfPSZGJwjBv1CL0aMD",
          text: textoLimpio,
          subseccion: $input.first().json.id_subseccion,
          libro: $input.first().json.id_libro,
        },
      ],
    },
  },
];

const items = $input.all();

// Filtrar solo los .mp3
const mp3Items = items.filter(item => item.json?.s3_path?.endsWith('.mp3'));

// Crear el objeto final
const result = {};

for (const item of mp3Items) {
  const path = item.json.s3_path;

  if (path.includes('audio_voz_1')) {
    result.audioF = path; // voz femenina
  } else if (path.includes('audio_voz_2')) {
    result.audioM = path; // voz masculina
  }
}

return [{ json: result }];
